mcp:tool-listener.mcp:parameters-schema:
{
        "type": "object",
        "properties": {
          "email": { "type": "string", "description": "The email address on the customer's orders." }
        },
        "required": ["email"],
        "additionalProperties": false
      }

{
        "type": "object",
        "properties": {
          "orderId": { "type": "string", "description": "Order number, like SO-24817." },
          "email": { "type": "string", "description": "The email address on the order." }
        },
        "required": ["orderId", "email"],
        "additionalProperties": false
      }

{
        "type": "object",
        "properties": {
          "orderId": { "type": "string", "description": "Order number, like SO-24903." },
          "email": { "type": "string", "description": "The email address on the order." }
        },
        "required": ["orderId", "email"],
        "additionalProperties": false
      }

{
        "type": "object",
        "properties": {
          "orderId": { "type": "string", "description": "Order number, like SO-24903." },
          "email": { "type": "string", "description": "The email address on the order." },
          "slotId": { "type": "string", "description": "A slotId returned by list_delivery_slots, like D8-AM." }
        },
        "required": ["orderId", "email", "slotId"],
        "additionalProperties": false
      }

{
        "type": "object",
        "properties": {
          "orderId": { "type": "string", "description": "Order number, like SO-24655." },
          "email": { "type": "string", "description": "The email address on the order." },
          "category": { "type": "string", "enum": ["DAMAGE", "DELAY", "DELIVERY", "OTHER"] },
          "summary": { "type": "string", "description": "What the customer reported and wants, in two or three sentences." }
        },
        "required": ["orderId", "email", "category", "summary"],
        "additionalProperties": false
      }
